(6950042, 1047505, 114225, '<td valign="top">Creative, and a bit creepy. Very much Son of Sam feel to this.</td>', 'Creative, and a bit creepy. Very much Son of Sam feel to this.', '2013-01-05 21:33:55.000000', NULL, 1),
